/** Enable the internal debug logs for the SDK */
export function setDebugMode(flag: boolean): void {
  DEBUG = flag;
}

const log =
  (level: 'error' | 'log' | 'warn'): typeof console.log =>
  (...args) => {
    if (DEBUG) {
      console[level](...args);
    }
  };

/** Wrapper around `console` functions to output only if the debug mode is enabled */
export const debug = {
  error: log('error'),
  warn: log('warn'),
  log: log('log'),
};
","// TODO: instead of polling could we use MutationObserver to check for dom changes and then compare URL's
export function pollUrlChanges(callback: (newUrl: string) => void, interval = 500): () => void {
  let initialUrl = window.location.href;

  const checkUrlChange = () => {
    const currentUrl = window.location.href;
    if (currentUrl !== initialUrl) {
      initialUrl = currentUrl;
      callback(currentUrl);
    }
  };

  const intervalId = setInterval(checkUrlChange, interval);
  return () => clearInterval(intervalId);
}
